import {interpretMessage,norm} from './assistant.mjs';
import {today,dayInMonth,firstInvoice,money,parts,monthShift} from './finance.mjs';
import {recurringDate,esc} from './analytics.mjs';
export function explicitDate(text,now=today()){
 const t=norm(text),iso=t.match(/\b(20\d{2}-\d{2}-\d{2})\b/),full=t.match(/\b(\d{1,2})\/(\d{1,2})\/(20\d{2})\b/);let date=iso?.[1]||(full?`${full[3]}-${full[2].padStart(2,'0')}-${full[1].padStart(2,'0')}`:null);
 if(date){const [y,m,d]=date.split('-').map(Number);return m>=1&&m<=12&&d>=1&&d<=31&&dayInMonth(`${y}-${String(m).padStart(2,'0')}`,d)===date?date:null;}
 if(/\b(hoje|ontem|amanha)\b/.test(t)){const d=new Date(now+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+(/\bontem\b/.test(t)?-1:/\bamanha\b/.test(t)?1:0));return d.toISOString().slice(0,10);}return null;
}
export function extractFields(text,D,now=today()){
 const t=norm(text),r=interpretMessage(text,D,now).draft,d={};
 const loose=text.match(/(?:^|[\s,;])((?:\d{1,3}(?:\.\d{3})+|\d+),\d{2})(?=$|[\s,;])/);if(!r.valor&&loose)r.valor=Number(loose[1].replaceAll('.','').replace(',','.'));
 for(const k of ['valor','categoria_id','subcategoria_id','pagador','quantidade','modalidade','frequencia'])if(r[k]!==undefined)d[k]=r[k];
 if(/\b(recebi|recebido|receita|salario|bolsa)\b/.test(t))d.tipo='entrada';else if(/\b(gastei|paguei|comprei|comprou|compra|despesa|gasto|pagar|pago)\b/.test(t))d.tipo='saida';
 if(!d.tipo&&/\b(restaurante|almoco|jantar|lanche|mercado|supermercado|gasolina|combustivel|farmacia|dizimo|oferta)\b/.test(t))d.tipo='saida';
 if(/\bfatura\b/.test(t)&&/\b(paguei|pagamento|pagar|pago)\b/.test(t))d.tipo='pagamento_fatura';
 const method=['pix','debito','credito','dinheiro','boleto','transferencia','deposito'].filter(x=>new RegExp('\\b'+x+'\\b').test(t));if(method.length===1)d.forma=method[0];
 // Card ownership is not the personal attribution of the spending.
 let who=t;for(const c of [...D.cartoes,...D.contas])who=who.replaceAll(norm(c.nome),'');
 if(/\bfamilia(?:r)?\b/.test(who))d.pessoa_id='';else {const people=D.pessoas.filter(p=>new RegExp('\\b'+norm(p.nome).replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b').test(who));if(people.length===1)d.pessoa_id=people[0].id;}
 const banks=D.contas.filter(c=>c.ativa&&(t.includes(norm(c.nome))||(/\bc6\b/.test(t)&&norm(c.nome).includes('c6'))||(/\binter\b/.test(t)&&norm(c.nome).includes('inter'))));if(banks.length===1)d.conta_id=banks[0].id;
 const cards=D.cartoes.filter(c=>c.ativo&&(t.includes(norm(c.nome))||(/\binter\b/.test(t)&&norm(c.nome).includes('inter'))||(/\bporto\b/.test(t)&&norm(c.nome).includes('porto'))||(/\bitau\b/.test(t)&&norm(c.nome).includes('itau'))));if(cards.length===1&&(/\b(cartao|credito|fatura)\b/.test(t))){d.cartao_id=cards[0].id;if(!d.forma&&d.tipo==='saida'&&!/\bfatura\b/.test(t))d.forma='credito';}
 if(d.tipo==='saida'&&/\b(restaurante|almoco|jantar|delivery|lanche)\b/.test(t)){const cat=D.categorias.find(c=>c.ativa&&c.tipo==='saida'&&/restaurante|delivery/.test(norm(c.nome)));if(cat)d.categoria_id=cat.id;}
 const date=explicitDate(text,now);if(date)d.data_prevista=date;
 if(/\b(paguei|pago|gastei|recebi|recebido)\b/.test(t))d.status='concluido';if(/\b(pendente|a pagar|a receber|vou pagar|vou receber)\b/.test(t))d.status='pendente';
 return d;
}
export function missingField(d,D,now=today()){
 if(!d.tipo)return 'tipo';if(!Number.isFinite(Number(d.valor))||Number(d.valor)<=0)return 'valor';if(!d.data_prevista)return 'data_prevista';if(!d.forma||d.tipo==='entrada'&&d.forma==='credito'||d.tipo==='pagamento_fatura'&&d.forma==='credito')return 'forma';
 if(d.forma==='credito'){if(!D.cartoes.some(c=>c.id===d.cartao_id&&c.ativo&&c.dia_fechamento&&c.dia_vencimento))return 'cartao_id';}
 else if(!D.contas.some(c=>c.id===d.conta_id&&c.ativa&&(d.forma==='dinheiro'?c.tipo==='dinheiro':c.tipo!=='dinheiro')))return 'conta_id';
 if(d.tipo==='pagamento_fatura'){if(!D.cartoes.some(c=>c.id===d.cartao_id&&c.ativo))return 'cartao_id';if(!d.fatura_mes)return 'fatura_mes';}
 if(d.pessoa_id===undefined)return 'pessoa_id';
 if(['entrada','saida'].includes(d.tipo)&&!D.categorias.some(c=>c.id===d.categoria_id&&c.ativa&&c.tipo===d.tipo))return 'categoria_id';
 if(d.forma!=='credito'&&d.data_prevista<=now&&!d.status)return 'status';return null;
}
export function normalizedDraft(d,D,now=today()){
 const x={...d,modalidade:d.modalidade||'unico',frequencia:d.frequencia||'mensal',quantidade:d.quantidade||1};
 if(x.forma==='credito'){x.conta_id=null;x.status='pendente';x.data_realizada=null;x.fatura_mes=x.fatura_mes||firstInvoice(x.data_prevista,D.cartoes.find(c=>c.id===x.cartao_id));}
 else {if(x.tipo!=='pagamento_fatura'){x.cartao_id=null;x.fatura_mes=null;}if(x.data_prevista>now)x.status='pendente';x.data_realizada=x.status==='concluido'?x.data_prevista:null;}
 return x;
}
const labels={tipo:'Tipo',valor:'Valor',data_prevista:'Data',forma:'Forma de pagamento',conta_id:'Conta',cartao_id:'Cartão',fatura_mes:'Fatura',pessoa_id:'De quem é',categoria_id:'Categoria / fonte',status:'Situação',descricao:'Descrição'};
const methods={pix:'Pix',debito:'Débito',credito:'Crédito',dinheiro:'Dinheiro',boleto:'Boleto',transferencia:'Transferência',deposito:'Depósito'};
const dateLabel=d=>d?.split('-').reverse().join('/')||'';
export function mountConversation(host,ctx){
 const {state:S,getData,saveDraft,undoPlans,editRecord,refreshData}=ctx;let currentQuestion=null;
 const data=()=>getData();
 const say=(role,text)=>S.messages.push({role,text});
 const choice=(field,value,label)=>`<button type="button" data-chat-choice="${esc(field)}" data-value="${esc(value)}">${esc(label)}</button>`;
 function options(field,d){const D=data();switch(field){case 'tipo':return [['saida','Saída'],['entrada','Entrada'],['pagamento_fatura','Pagamento de fatura']];case 'forma':return Object.entries(methods).filter(([k])=>!(['entrada','pagamento_fatura'].includes(d.tipo)&&k==='credito'));case 'conta_id':return D.contas.filter(c=>c.ativa&&(d.forma==='dinheiro'?c.tipo==='dinheiro':c.tipo!=='dinheiro')).map(c=>[c.id,c.nome]);case 'cartao_id':return D.cartoes.filter(c=>c.ativo).map(c=>[c.id,c.nome]);case 'pessoa_id':return [...D.pessoas.map(p=>[p.id,p.nome]),['','Família']];case 'categoria_id':return D.categorias.filter(c=>c.ativa&&c.tipo===d.tipo).map(c=>[c.id,c.nome]);case 'status':return [['concluido',d.tipo==='entrada'?'Já recebi':'Já paguei'],['pendente',d.tipo==='entrada'?'A receber':'Ainda vou pagar']];default:return [];}}
 function summary(item){const d=item.draft,D=data(),who=d.pessoa_id===''?'Família':D.pessoas.find(p=>p.id===d.pessoa_id)?.nome||'Pessoa a definir',place=d.forma==='credito'?D.cartoes.find(c=>c.id===d.cartao_id)?.nome:D.contas.find(c=>c.id===d.conta_id)?.nome;return `${d.tipo==='entrada'?'Entrada':d.tipo==='pagamento_fatura'?'Pagamento de fatura':'Saída'} · ${money(d.valor)} · ${dateLabel(d.data_prevista)} · ${methods[d.forma]||''} ${place||''} · ${who}${d.modalidade==='parcelado'?' · '+d.quantidade+' parcelas':d.modalidade==='recorrente'?' · Recorrência mensal':''}${d.fatura_mes?' · Fatura '+d.fatura_mes.split('-').reverse().join('/'):''}`;}
 function draw(){
 const D=data(),item=S.queue?.[S.index||0],d=item?.draft||{};currentQuestion=S.editField||(!S.confirm&&!S.error&&item?missingField(d,D):null);
 let controls='';
 if(S.busy)controls='<p class="chat-status" role="status">Salvando…</p>';
 else if(S.error)controls=`<p class="pill-warning">${esc(S.error)}</p><button type="button" data-chat-command="retry" class="primary">Tentar novamente</button>${!S.retryOnly?'<button type="button" data-chat-command="repair">Corrigir dados</button>':''}`;
 else if(S.confirm)controls=`<h3>Confira antes de registrar</h3>${S.queue.map((q,i)=>`<div class="chat-confirm"><p>${esc(summary(q))}</p><p>${esc(q.draft.descricao)}</p>${q.draft.modalidade==='parcelado'?`<p>${parts(q.draft.valor,q.draft.quantidade).slice(0,12).map((v,j)=>`${j+1}/${q.draft.quantidade}: ${money(v)}`).join(' · ')}</p>`:''}${!q.done?`<button type="button" data-chat-review="${i}">Ajustar</button>`:'<span>Já registrado</span>'}</div>`).join('')}<div class="chat-choices"><button type="button" data-chat-command="confirm" class="primary">${S.queue.some(x=>x.editId)?'Salvar correção':'Confirmar e registrar'}</button><button type="button" data-chat-command="discard">Cancelar</button></div>`;
 else if(currentQuestion){const question={tipo:'É uma entrada, uma saída ou um pagamento de fatura?',valor:'Qual é o valor?',data_prevista:'Em qual data? Informe dia, mês e ano, ou escolha abaixo.',forma:'Qual foi a forma de pagamento?',conta_id:d.forma==='dinheiro'?'Qual carteira de dinheiro?':'Qual conta ou banco?',cartao_id:'Qual cartão?',fatura_mes:'De qual mês e ano é a fatura que você está pagando?',pessoa_id:'De quem é este lançamento?',categoria_id:d.tipo==='entrada'?'Qual é a fonte da receita?':'Em qual categoria entra esse gasto?',status:d.tipo==='entrada'?'Você já recebeu esse valor?':'Esse valor já foi pago?',descricao:'Qual descrição você quer usar?'}[currentQuestion];controls=`<h3>${question}</h3><div class="chat-choices">${options(currentQuestion,d).map(([v,l])=>choice(currentQuestion,v,l)).join('')}${currentQuestion==='data_prevista'?choice('data_prevista',today(),'Hoje')+choice('data_prevista',explicitDate('ontem'),'Ontem'):''}</div>${['data_prevista','fatura_mes'].includes(currentQuestion)?`<div class="chat-date"><input aria-label="${labels[currentQuestion]}" id="chat-date" type="${currentQuestion==='fatura_mes'?'month':'date'}"><button type="button" data-chat-command="date">Usar esta data</button></div>`:''}${['conta_id','cartao_id','categoria_id'].includes(currentQuestion)&&!options(currentQuestion,d).length?'<p class="pill-warning">Cadastre essa opção em Contas, Cartões ou Cadastros antes de continuar.</p>':''}<button type="button" class="quiet" data-chat-command="discard">Cancelar este envio</button>`;}
 else if(S.chooseEdit){controls='<h3>O que deseja corrigir?</h3><div class="chat-choices">'+Object.entries(labels).filter(([k])=>k!=='tipo').map(([k,l])=>`<button type="button" data-chat-editfield="${k}">${l}</button>`).join('')+'</div><button type="button" data-chat-command="discard">Cancelar correção</button>';}
 host.innerHTML=`<section class="panel assistant-panel"><div class="assistant-intro"><span class="assistant-symbol">✦</span><h2>Registre pela conversa</h2><p>Conte o que aconteceu. Se faltar algum dado, eu pergunto.</p></div><div id="chat-history" role="log" aria-live="polite">${S.messages.map(m=>`<div class="${m.role==='user'?'chat-user':'chat-answer'}">${esc(m.text)}</div>`).join('')}${S.saved.map((x,i)=>`<article class="chat-draft"><span class="tag">${x.undone?'Desfeito':x.edited?'Atualizado':'Registrado'}</span><p>${esc(summary(x))}</p><p>${esc(x.draft.descricao)}</p>${!x.undone?`<div class="chat-choices"><button type="button" data-chat-undo="${i}">Desfazer</button><button type="button" data-chat-correct="${i}">Corrigir</button></div>`:''}</article>`).join('')}</div><div class="chat-question" aria-live="polite">${controls}</div><form id="chat-form"><label for="chat-text">${currentQuestion?'Sua resposta':'Sua mensagem'}<textarea id="chat-text" rows="2" maxlength="2000" placeholder="Ex.: Gastei 85 no mercado" ${S.busy||S.confirm||S.error||S.chooseEdit?'disabled':''} required></textarea></label><div class="assistant-compose"><button type="button" data-chat-command="dictate" class="quiet">Ditado por voz</button><button class="primary" ${S.busy||S.confirm||S.error||S.chooseEdit?'disabled':''}>Enviar</button></div><p class="small">Texto e ditado pelo teclado. Áudios gravados, fotos e PDFs ainda não estão disponíveis. Os rascunhos desta conversa ficam abertos só nesta sessão; os lançamentos salvos ficam no painel.</p></form></section>`;
 if(S.busy)host.querySelectorAll('button,input,textarea').forEach(e=>e.disabled=true);
 host.querySelector('#chat-form').onsubmit=async e=>{e.preventDefault();const input=host.querySelector('#chat-text').value.trim();if(input)await receive(input);};
 }
 function validateAnswer(field,value,d){const D=data();if(field==='valor'){const s=value.replace(/^r\$\s*/i,'').trim();if(!/^\d+(?:[,.]\d{1,2})?$/.test(s))return false;const n=Number(s.replace(',','.'));if(n<=0)return false;d.valor=n;return true;}if(field==='data_prevista'){const dt=explicitDate(value);if(!dt)return false;d.data_prevista=dt;if(d.forma==='credito')delete d.fatura_mes;return true;}if(field==='fatura_mes'){if(!/^20\d{2}-(0[1-9]|1[0-2])$/.test(value))return false;d.fatura_mes=value;return true;}if(field==='descricao'){d.descricao=value.slice(0,200);return true;}const o=options(field,d),v=o.find(([id,name])=>id===value||norm(name)===norm(value));if(!v)return false;d[field]=v[0];if(field==='forma'){if(d.forma==='credito'){delete d.conta_id;delete d.fatura_mes;}else{delete d.cartao_id;delete d.fatura_mes;}}if(field==='cartao_id')delete d.fatura_mes;if(field==='categoria_id')delete d.subcategoria_id;return true;}
 async function receive(text){if(S.busy||S.error||S.confirm)return;say('user',text);if(!S.queue.length){const lines=text.split(/\n+/).map(s=>s.trim()).filter(Boolean);if(lines.length>10){say('assistant','Envie até 10 lançamentos por vez, um por linha.');draw();return;}if(lines.some(s=>/\b(?:e|tambem)\s+(?:paguei|gastei|recebi|comprei|\d)/.test(norm(s)))){say('assistant','Para separar os valores corretamente, envie um lançamento por linha.');draw();return;}S.queue=lines.map(line=>({id:crypto.randomUUID(),draft:{descricao:line.slice(0,200),...extractFields(line,data())}}));S.index=0;}
 else {const item=S.queue[S.index],field=currentQuestion;let accepted=false;if(field)accepted=validateAnswer(field,text,item.draft);if(!S.editField){const fields=extractFields(text,data());for(const [k,v] of Object.entries(fields)){if(k!=='tipo'||!item.draft.tipo)item.draft[k]=v;}accepted=accepted||field&&item.draft[field]!==undefined;}if(!accepted){say('assistant','Não consegui identificar essa resposta. Use uma das opções ou informe o dado solicitado.');draw();return;}if(S.editField){S.editField=null;S.chooseEdit=false;}}
 await advance();}
 async function advance(){
 for(let i=0;i<S.queue.length;i++){const item=S.queue[i],d=item.draft;if(d.forma==='dinheiro'&&!d.conta_id){const wallets=data().contas.filter(a=>a.ativa&&a.tipo==='dinheiro');if(wallets.length===1)d.conta_id=wallets[0].id;}const missing=missingField(d,data());if(missing){S.index=i;S.confirm=false;draw();return;}}
 S.queue.forEach(item=>item.draft=normalizedDraft(item.draft,data()));
 const duplicate=S.queue.some(item=>!item.editId&&data().fin_movimentos.some(m=>m.status!=='cancelado'&&Number(m.valor)===Number(item.draft.valor)&&m.tipo===item.draft.tipo&&(m.data_realizada||m.data_prevista)===item.draft.data_prevista));
 if(duplicate)say('assistant','Encontrei um lançamento do mesmo tipo, data e valor. Confira para evitar duplicidade.');
 if(S.queue.length>1||S.queue.some(x=>x.draft.modalidade!=='unico'||x.editId)||duplicate){S.confirm=true;draw();return;}await persist();
 }
 async function persist(){if(S.busy)return;S.busy=true;S.error=null;draw();try{for(const item of S.queue){if(item.done)continue;if(item.editId)await editRecord(item);else await saveDraft(item);item.done=true;if(item.savedIndex!==undefined){S.saved[item.savedIndex].draft={...item.draft};S.saved[item.savedIndex].edited=true;}else S.saved.push({...item,draft:{...item.draft}});}S.queue=[];S.confirm=false;S.index=0;say('assistant','Registrado. Você pode corrigir ou desfazer abaixo.');try{await refreshData();}catch{say('assistant','O registro foi confirmado, mas o resumo não atualizou. Use Atualizar no painel.');}}catch(e){S.retryOnly=!e.status;S.error=e.message||'Não recebi confirmação do servidor. Tente novamente; o mesmo envio não será duplicado.';}finally{S.busy=false;draw();}}
 host.onclick=async e=>{const b=e.target.closest('button');if(!b||S.busy)return;try{
 if(b.dataset.chatChoice!==undefined){const item=S.queue[S.index],field=b.dataset.chatChoice;if(validateAnswer(field,b.dataset.value,item.draft)){say('user',b.textContent);S.editField=null;S.chooseEdit=false;await advance();}return;}
 if(b.dataset.chatReview!==undefined){S.index=Number(b.dataset.chatReview);S.confirm=false;S.chooseEdit=true;draw();return;}
 if(b.dataset.chatEditfield){const f=b.dataset.chatEditfield,d=S.queue[S.index].draft;if(f==='cartao_id'&&d.forma!=='credito'&&d.tipo!=='pagamento_fatura'){say('assistant','Para usar um cartão de crédito, altere primeiro a forma de pagamento.');draw();return;}if(f==='fatura_mes'&&d.forma!=='credito'&&d.tipo!=='pagamento_fatura'){say('assistant','Este lançamento não tem fatura.');draw();return;}S.editField=f;S.chooseEdit=false;draw();return;}
 if(b.dataset.chatUndo!==undefined){if(S.queue.length){say('assistant','Finalize ou cancele o envio em andamento antes de desfazer outro.');draw();return;}const x=S.saved[Number(b.dataset.chatUndo)];S.busy=true;draw();try{await undoPlans(x);x.undone=true;say('assistant','Lançamento desfeito.');await refreshData();}finally{S.busy=false;draw();}return;}
 if(b.dataset.chatCorrect!==undefined){if(S.queue.length){say('assistant','Finalize ou cancele o envio em andamento antes de corrigir outro.');draw();return;}const i=Number(b.dataset.chatCorrect),x=S.saved[i];await refreshData();const rows=data().fin_movimentos.filter(m=>m.plano_id===x.id&&m.status!=='cancelado');if(rows.length!==1){say('assistant','Este envio tem várias parcelas ou recorrências. Para corrigir uma ocorrência específica, use Editar em Movimentações. Você pode desfazer a série inteira aqui.');draw();return;}S.queue=[{id:x.id,editId:rows[0].id,savedIndex:i,draft:{...x.draft,modalidade:'unico'}}];S.index=0;S.chooseEdit=true;draw();return;}
 const cmd=b.dataset.chatCommand;if(cmd==='confirm'){S.confirm=false;await persist();}else if(cmd==='retry'){S.error=null;await persist();}else if(cmd==='repair'){S.error=null;S.index=Math.max(0,S.queue.findIndex(x=>!x.done));S.chooseEdit=true;draw();}else if(cmd==='discard'){S.queue=[];S.index=0;S.confirm=false;S.editField=null;S.chooseEdit=false;say('assistant',S.saved.length?'Envio em andamento cancelado. Os registros já salvos continuam no painel.':'Envio cancelado. Nenhum lançamento foi salvo.');draw();}else if(cmd==='date'){const v=host.querySelector('#chat-date').value;if(validateAnswer(currentQuestion,v,S.queue[S.index].draft)){say('user',v);S.editField=null;S.chooseEdit=false;await advance();}}else if(cmd==='dictate'){host.querySelector('#chat-text').focus();say('assistant','Toque no microfone do teclado do celular ou tablet para ditar neste campo.');draw();host.querySelector('#chat-text').focus();}
 }catch(err){say('assistant',err.message||'Não foi possível concluir. Tente novamente.');S.busy=false;draw();}};
 draw();return {receive,advance,draw};
}
